363:         return [pscustomobject]@{ State = 'done'; Exit = $(if ($ok) { 0 } else { 1 }); Text = "done, exit $exitText"; Finished = $finished; Of = $of }
368:         $age = $(if ($started) { $Now - $started } else { [TimeSpan]::MaxValue })
369:         if ($age.TotalSeconds -lt $script:DetachedStartGraceSec) {
370:             return [pscustomobject]@{ State = 'starting'; Exit = 2; Text = "starting - the background has not reported yet (started $(Format-DetachedSpan $age) ago)"; Finished = $finished; Of = $of }
374:         return [pscustomobject]@{ State = 'never-started'; Exit = 1; Text = "never started - no background process reported within $($script:DetachedStartGraceSec) s of $startedText; if one starts late it still reports and the run reads running again (its log may say why)"; Finished = $finished; Of = $of }
378:         return [pscustomobject]@{ State = 'elsewhere'; Exit = 2; Text = "running on host $recordHost since $startedText (pid $bgPid) - its liveness cannot be checked from this host"; Finished = $finished; Of = $of }
381:         $since = $(if ($started) { " ($(Format-DetachedSpan ($Now - $started)))" } else { '' })
382:         return [pscustomobject]@{ State = 'running'; Exit = 2; Text = "running since $startedText$since, $finished of $of members finished"; Finished = $finished; Of = $of }
384:     return [pscustomobject]@{ State = 'died'; Exit = 1; Text = "died - its background process (pid $bgPid) is gone without a final status, $finished of $of members finished; its recovery records are judged by the next run of the task as usual"; Finished = $finished; Of = $of }
387: # The line codex-findings.ps1 -List prints for a detached run of the task that is not done ('' for
388: # a done one): `detached <id8>: running since <t>, k of N members finished`, or its died,
