394:     return "detached $($Run.Id8): $($j.Text) (codex-consult.ps1 -Task $Task -Status -Id $($Run.Id8))"
397: # The SessionStart hook's phrase over every task of the collab root (D6): '' when no detached run
398: # is running, died or finished in the last $FinishedHours hours; else e.g. "; 1 detached
399: # consultation running (task t)" or "; detached consultations: 1 running (task t), 1 finished
400: # (task u)". Status files only; nothing is written.
401: function Get-DetachedPhrase {
