403:     if (-not $CollabRoot -or -not [IO.Directory]::Exists($CollabRoot)) { return '' }
406:     foreach ($dir in [IO.Directory]::GetDirectories($CollabRoot)) {
408:         foreach ($run in (Read-DetachedRuns -TaskDir $dir)) {
409:             $j = Get-DetachedJudgement -Record $run.Record -Problem ([string]$run.Error) -Now $Now
412:             elseif (@('died', 'never-started', 'unreadable') -contains $j.State) { $cat = 'died' }
433:         return "; $total detached consultation$(if ($total -ne 1) { 's' }) $($parts[0])"
436:     return "; detached consultations: $($withCounts -join ', ')"

