124: function New-Acc {
125:     param([string]$Lineage, [string]$Key)
126:     return [pscustomobject]@{
127:         Lineage = $Lineage; Purpose = $Key; Consults = 0; Usable = 0; Prose = 0; Failed = 0
128:         Raised = 0; Verified = 0; Rejected = 0; Wontfix = 0; Superseded = 0; Open = 0
129:         Accept = 0; Hold = 0; Reject = 0; Advise = 0; Yes = 0; Partly = 0; No = 0; Unique = 0; PanelRaised = 0
130:         Walls = (New-Object System.Collections.Generic.List[double]); TokensIn = [long]0; TokensOut = [long]0
131:     }
132: }
133: $rows = @{}
134: $totalRows = @{}
