136: $identityOf = @{}
137: function Get-Accs {
138:     param([string]$Lineage, [string[]]$Keys)
139:     $list = New-Object System.Collections.Generic.List[object]
140:     foreach ($k in $Keys) {
141:         $key = "$Lineage`t$k"
142:         if (-not $rows.ContainsKey($key)) { $rows[$key] = New-Acc $Lineage $k }
143:         $list.Add($rows[$key])
144:     }
145:     if (-not $totalRows.ContainsKey($Lineage)) { $totalRows[$Lineage] = New-Acc $Lineage '(total)' }
146:     $list.Add($totalRows[$Lineage])
147:     return , ([object[]]$list.ToArray())
148: }
149: # The row keys of a consultation (or of a mark without one): its purpose, or (-By topic) each of
150: # its topics; '(none)' without.
151: function Get-RowKeys {
152:     param([string]$Purpose, [object[]]$Topics)
153:     if ($By -eq 'topic') {
154:         $t = @(@($Topics) | Where-Object { $_ } | ForEach-Object { ([string]$_).ToLowerInvariant() } | Select-Object -Unique)
155:         if ($t.Count -eq 0) { return , ([string[]]@('(none)')) }
156:         return , ([string[]]$t)
157:     }
158:     if (-not $Purpose) { $Purpose = '(none)' }
159:     return , ([string[]]@($Purpose))
160: }
161: # A finding's location keys ("path:line"; "path:" without a line) for the unique-findings measure.
162: function Get-LocationKeys {
163:     param($Finding)
164:     $keys = New-Object System.Collections.Generic.List[string]
165:     foreach ($l in @(Get-PropertyValue $Finding 'locations' @() | Where-Object { $null -ne $_ })) {
166:         $path = [string](Get-PropertyValue $l 'path' '')
167:         if (-not $path) { continue }
168:         $line = Get-PropertyValue $l 'line' $null
169:         $keys.Add("$($path.Replace('\', '/')):$(if ($null -ne $line) { [string]$line } else { '' })")
170:     }
171:     return , ([string[]]$keys.ToArray())
