183:     # a consultation's rows by its n (the findings' join, within the task) and by its consult_id
184:     # (the marks' join); its panel id (the unique-findings measure)
185:     $keyOf = @{}
186:     $keyOfId = New-Object System.Collections.Hashtable ([StringComparer]::OrdinalIgnoreCase)
