216:             $cached = Get-IntValue $usage 'cached_input_tokens'
217:             $out = Get-IntValue $usage 'output_tokens'
218:             if ($null -ne $in) { $tin = [Math]::Max([long]0, $in - $(if ($null -ne $cached) { $cached } else { 0 })) }
219:             if ($null -ne $out) { $tout = $out }
220:         }
221:         foreach ($acc in $accs) {
222:             $acc.Consults++
223:             if ($usable) { $acc.Usable++; if ($prose) { $acc.Prose++ } } else { $acc.Failed++ }
224:             switch ($verdict) {
225:                 'ACCEPT' { $acc.Accept++ }
226:                 'HOLD' { $acc.Hold++ }
227:                 'REJECT' { $acc.Reject++ }
228:                 'ADVISE' { $acc.Advise++ }
229:             }
