233:         }
234:     }
235:     $findingsList = @(@(Get-PropertyValue $store 'findings' @()) | Where-Object { $null -ne $_ })
236:     # (wave 26, D10) the unique-findings measure: a finding raised by a panel member is unique when
237:     # no finding of ANOTHER member of the same panel shares one of its locations
238:     $locsOf = @{}
239:     for ($i = 0; $i -lt $findingsList.Count; $i++) { $locsOf[$i] = Get-LocationKeys $findingsList[$i] }
