5865: # The routing seed (D4): SHA-256 over the UTF-8 text `<task>|<purpose>|<brief sha256>|<the eligible
5866: # lineages, sorted ordinally, joined by ','>|<nonce>`. { Hex; Bytes; Text }.
5867: function Get-PanelSeed {
5868:     param([string]$Task, [string]$Purpose, [string]$BriefSha, [string[]]$Lineages, [string]$Nonce)
5869:     $sorted = [string[]]@($Lineages | ForEach-Object { [string]$_ })
5870:     [Array]::Sort($sorted, [StringComparer]::Ordinal)
5871:     $text = "$Task|$Purpose|$BriefSha|$($sorted -join ',')|$Nonce"
5872:     $sha = [System.Security.Cryptography.SHA256]::Create()
5873:     try { $bytes = $sha.ComputeHash($script:Utf8NoBom.GetBytes($text)) } finally { $sha.Dispose() }
5874:     return [pscustomobject]@{ Hex = (ConvertTo-HexString $bytes); Bytes = [byte[]]$bytes; Text = $text }
5875: }
5876: 
5877: # A uniform in [0, 1) from 8 bytes of $Hash at $Offset (D4): their top 53 bits (big-endian) / 2^53
5878: # - exact in a double, so both runtimes agree to the bit.
5879: function ConvertTo-Uniform53 {
5880:     param([byte[]]$Hash, [int]$Offset = 0)
5881:     $v = [long]0
5882:     for ($i = 0; $i -lt 6; $i++) { $v = $v * 256 + [long]$Hash[$Offset + $i] }
5883:     $v = $v * 32 + ([long]$Hash[$Offset + 6] -shr 3)
5884:     return ([double]$v / 9007199254740992.0)
5885: }
5886: 
5887: # The two uniforms of draw slot $Slot (1-based over the panel's seats; D4): SHA-256(seed ||
5888: # the slot as 4 bytes big-endian) - bytes 0..7 pick (the weighted draw), bytes 8..15 decide
5889: # exploration (< 0.2). { Pick; Explore; Hex }.
5890: function Get-SlotUniforms {
5891:     param([byte[]]$Seed, [int]$Slot)
5892:     $buf = New-Object byte[] ($Seed.Length + 4)
5893:     [Array]::Copy($Seed, $buf, $Seed.Length)
5894:     $buf[$Seed.Length] = [byte](($Slot -shr 24) -band 255)
5895:     $buf[$Seed.Length + 1] = [byte](($Slot -shr 16) -band 255)
5896:     $buf[$Seed.Length + 2] = [byte](($Slot -shr 8) -band 255)
5897:     $buf[$Seed.Length + 3] = [byte]($Slot -band 255)
5898:     $sha = [System.Security.Cryptography.SHA256]::Create()
5899:     try { $h = $sha.ComputeHash($buf) } finally { $sha.Dispose() }
5900:     return [pscustomobject]@{ Pick = (ConvertTo-Uniform53 -Hash $h -Offset 0); Explore = (ConvertTo-Uniform53 -Hash $h -Offset 8); Hex = (ConvertTo-HexString $h) }
5901: }
5902: 
5903: # The seats of a routed panel (D1, D4): $Candidates (roster order) of { Position; Lab; Weight;
5904: # Pinned }; $K seats. Pinned candidates take the first seats (rule `required`, roster order); then
5905: # slot by slot: while fewer than min(K, number of labs with a candidate weighing >= $Neutral) of
5906: # those labs are seated, the draw is restricted to candidates of a lab not yet seated that weigh
5907: # >= $Neutral (rule lab-draw / lab-explore); otherwise it draws from every candidate left
5908: # (rank-draw / rank-explore). A slot explores (a uniform pick from the same pool) when its second
5909: # uniform is below $Explore; else the weighted pick: the first candidate, in roster order, whose
5910: # running weight sum exceeds uniform x the pool's weight sum. The winner leaves the pool.
5911: # Returns the seats in order: { Slot; Candidate; Rule }.
5912: function Invoke-PanelDraw {
5913:     param([object[]]$Candidates, [int]$K, [byte[]]$Seed, [double]$Neutral = $script:RoutingNeutral, [double]$Explore = $script:RoutingExplore)
5914:     $seats = New-Object System.Collections.Generic.List[object]
5915:     $left = New-Object System.Collections.Generic.List[object]
5916:     foreach ($c in @($Candidates | Where-Object { $_ })) {
5917:         if ($c.Pinned) { $seats.Add([pscustomobject]@{ Slot = $seats.Count + 1; Candidate = $c; Rule = 'required' }) } else { $left.Add($c) }
5918:     }
5919:     $goodLabs = @(@($Candidates | Where-Object { $_ -and [double]$_.Weight -ge $Neutral }) | ForEach-Object { [string]$_.Lab } | Select-Object -Unique)
5920:     $reserve = [Math]::Min($K, $goodLabs.Count)
5921:     while ($seats.Count -lt $K -and $left.Count -gt 0) {
5922:         $slot = $seats.Count + 1
5923:         $seatedLabs = @($seats | ForEach-Object { [string]$_.Candidate.Lab } | Select-Object -Unique)
5924:         $covered = @($seatedLabs | Where-Object { $goodLabs -contains $_ }).Count
5925:         $pool = @()
5926:         $kind = 'rank'
5927:         if ($covered -lt $reserve) {
5928:             $pool = @($left | Where-Object { $seatedLabs -notcontains [string]$_.Lab -and [double]$_.Weight -ge $Neutral })
5929:             if ($pool.Count -gt 0) { $kind = 'lab' }
5930:         }
5931:         if ($pool.Count -eq 0) { $pool = @($left.ToArray()); $kind = 'rank' }
5932:         $u = Get-SlotUniforms -Seed $Seed -Slot $slot
5933:         $winner = $null
5934:         $rule = ''
5935:         if ($u.Explore -lt $Explore) {
5936:             $idx = [int][Math]::Floor($u.Pick * $pool.Count)
5937:             if ($idx -ge $pool.Count) { $idx = $pool.Count - 1 }
5938:             $winner = $pool[$idx]
5939:             $rule = "$kind-explore"
5940:         } else {
5941:             $total = 0.0
5942:             foreach ($c in $pool) { $total += [double]$c.Weight }
5943:             $target = $u.Pick * $total
5944:             $acc = 0.0
5945:             foreach ($c in $pool) {
5946:                 $acc += [double]$c.Weight
5947:                 if ($target -lt $acc) { $winner = $c; break }
5948:             }
5949:             if ($null -eq $winner) { $winner = $pool[$pool.Count - 1] }
5950:             $rule = "$kind-draw"
5951:         }
5952:         $seats.Add([pscustomobject]@{ Slot = $slot; Candidate = $winner; Rule = $rule })
5953:         [void]$left.Remove($winner)
5954:     }
5955:     return , ([object[]]$seats.ToArray())
5956: }
