6050: # The routing record as console lines (the panel run and its dry run print the same).
6051: function Format-RoutingLines {
6052:     param($Routing, [string]$Purpose = '')
6053:     $lines = New-Object System.Collections.Generic.List[string]
6054:     $sizeText = "size $($Routing.size) ($(if ($Routing.size_source -eq 'purpose') { "the default of purpose $(if ($Purpose) { $Purpose } else { 'none' })" } else { $Routing.size_source }))"
6055:     if ($Routing.mode -eq 'routed') {
6056:         $lines.Add("Routing: routed by the ratings - $sizeText; seed $($Routing.seed.Substring(0, 12)) (nonce $($Routing.nonce) from $($Routing.nonce_source)); exploration $($script:RoutingExplore) per slot")
6057:     } else {
6058:         $why = $(if ($Routing.fallback) { "fallback: $($Routing.fallback) - no eligible reviewer has $($script:RoutingMinRatings) ratings in $($script:RoutingWindowDays) days" } else { '-PanelOrder roster' })
6059:         $lines.Add("Routing: roster order ($why) - $sizeText")
6060:     }
6061:     $el = @($Routing.eligible | ForEach-Object { "#$($_.position) $($_.lineage) (lab $($_.lab)$(if ($_.lab_source -ne 'roster') { " by $($_.lab_source)" }); score $(([double]$_.score).ToString('0.###', $script:Invariant)) $($_.basis)$(if ([double]$_.ratings -gt 0) { " of $(([double]$_.ratings).ToString('0.##', $script:Invariant))" })$(if ($_.required) { '; required' }))" })
6062:     $lines.Add("  eligible: $(if ($el.Count -gt 0) { $el -join ', ' } else { '(none)' })")
6063:     $pk = @($Routing.picked | ForEach-Object { "$($_.slot). #$($_.position) $($_.lineage) ($($_.rule))" })
6064:     $lines.Add("  picked  : $(if ($pk.Count -gt 0) { $pk -join ', ' } else { '(none)' })")
6065:     if (@($Routing.required).Count -gt 0) { $lines.Add("  required: $(@($Routing.required) -join ', ')") }
6066:     return , ([string[]]$lines.ToArray())
6067: }
