1968: # The ledger entry a panel member recorded (the task's sessions.json, read tolerantly).
1969: function Find-PanelEntry {
1970:     param([string]$Path, [string]$PanelId, [int]$Position)
1971:     if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return $null }
1972:     $data = $null
1973:     try { $data = ConvertFrom-Json -InputObject (Read-SharedText -Path $Path) } catch { return $null }
1974:     $found = $null
1975:     foreach ($c in @(Get-PropertyValue (Get-PropertyValue $data 'codex' $null) 'consults' @())) {
1976:         $pr = Get-PropertyValue $c 'panel' $null
1977:         if ($null -ne $pr -and [string](Get-PropertyValue $pr 'id' '') -eq $PanelId -and [string](Get-PropertyValue $pr 'position' '') -eq [string]$Position) { $found = $c }
1978:     }
1979:     return $found
