720: # (wave 26, F08-2) A TERMINAL status write (the run's own final write, the background's
721: # confirmation): up to 3 attempts, 250 ms apart. Returns '' when written, else the last error.
722: function Write-DetachedStatusRetry {
723:     param([string]$Path, $Record)
724:     $last = ''
725:     for ($attempt = 1; $attempt -le 3; $attempt++) {
726:         try { Write-DetachedStatus -Path $Path -Record $Record; return '' } catch { $last = ConvertTo-OneLine $_.Exception.Message }
727:         if ($attempt -lt 3) { Start-Sleep -Milliseconds 250 }
728:     }
729:     return $last
730: }
