792: # -Artifact a,b arrives as ONE string through `powershell -File`: each value is split on commas
793: # unless the whole value names an existing file (absolute, or relative to one of $Bases).
794: function Split-ArtifactArgument {
795:     param([string[]]$Values, [string[]]$Bases)
796:     $list = New-Object System.Collections.Generic.List[string]
797:     foreach ($a in @($Values)) {
798:         if (-not $a -or -not $a.Trim()) { continue }
799:         $a = $a.Trim()
800:         $whole = -not $a.Contains(',')
801:         if (-not $whole) {
802:             if ([IO.Path]::IsPathRooted($a)) { $whole = Test-Path -LiteralPath $a -PathType Leaf }
803:             else {
804:                 foreach ($base in $Bases) {
805:                     if (Test-Path -LiteralPath (Join-Path $base $a) -PathType Leaf) { $whole = $true; break }
806:                 }
807:             }
808:         }
809:         if ($whole) { $list.Add($a) }
810:         else { foreach ($piece in $a.Split(',')) { if ($piece.Trim()) { $list.Add($piece.Trim()) } } }
811:     }
812:     return , ([string[]]$list.ToArray())
813: }
