816: # `starting` record ONCE, starts the background, prints three lines and exits 0 - or refuses (exit
817: # 1) with nothing left behind. $Members: the planned members (pending; a roster-skipped entry
818: # skipped); $Budget: D4; $Plan: what runs; $BriefFull, $ArtifactFull: absolute (D8); $Warnings:
819: # what a real run prints before it starts. Reads the run's variables ($taskDir, $collabRoot,
820: # $callerCwd, $Task, $Purpose, $ReplyName).
821: function Start-DetachedRun {
822:     param([string]$Kind, [object[]]$Members, [int]$Budget, [string]$Plan, [string]$BriefFull = '', [string[]]$ArtifactFull = @(), [string[]]$Warnings = @())
823:     # The background's arguments: this call's, minus -Detach, with the paths absolute (D8).
824:     $bgArgs = @{}
825:     foreach ($k in $script:ScriptBound.Keys) {
826:         if ($k -eq 'Detach' -or $script:CommonParameterNames -contains $k) { continue }
827:         $bgArgs[$k] = $script:ScriptBound[$k]
