830:     if (@($ArtifactFull).Count -gt 0) { $bgArgs['Artifact'] = [string[]]@($ArtifactFull) }
831:     $bgArgs['CollabDir'] = $collabRoot
832:     # The id: a guid whose id8 names no status or log file of the task yet (D7). TEST HOOK:
833:     # CODEX_CONSULT_TEST_DETACH_GUIDS=<guid>[,<guid>...] - tried first, in that order.
834:     $tries = New-Object System.Collections.Generic.List[string]
835:     foreach ($g in ([string]$env:CODEX_CONSULT_TEST_DETACH_GUIDS).Split(',')) {
836:         if ($g.Trim() -match '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$') { $tries.Add($g.Trim().ToLowerInvariant()) }
