838:     for ($i = 0; $i -lt 16; $i++) { $tries.Add([guid]::NewGuid().ToString()) }
839:     try { [void][IO.Directory]::CreateDirectory($taskDir) } catch { Stop-WithError "could not create the task directory '$taskDir' ($(ConvertTo-OneLine $_.Exception.Message)); nothing was started." }
840:     $newId = ''
841:     $paths = $null
842:     foreach ($cand in $tries) {
843:         $p = Get-DetachedPaths -TaskDir $taskDir -Id $cand
844:         if ((Test-Path -LiteralPath $p.Status) -or (Test-Path -LiteralPath $p.Log) -or (Test-Path -LiteralPath $p.Prompt)) { continue }
845:         $newId = $cand
846:         $paths = $p
847:         break
848:     }
