850:     # (wave 26, F11-2) an inline -Prompt goes to <task>/.consult.detached-<id8>.prompt.txt (UTF-8,
851:     # gitignored like the log); the record's args name only that file (PromptFile), so a run that
852:     # never starts leaves no prompt text in its status file - the background reads the file and
853:     # removes it; -Status -Prune removes a left-over one with the run's other files
854:     $promptFile = ''
855:     if ($bgArgs.ContainsKey('Prompt') -and [string]$bgArgs['Prompt']) {
856:         $promptFile = $paths.Prompt
857:         try { Write-Utf8NoBom -Path $promptFile -Text ([string]$bgArgs['Prompt']) } catch {
858:             Stop-WithError "could not write the prompt file '$promptFile' ($(ConvertTo-OneLine $_.Exception.Message)); nothing was started."
859:         }
860:         $bgArgs.Remove('Prompt')
861:         $bgArgs['PromptFile'] = $promptFile
862:     }
863:     # The background's command line.
864:     $hostExe = (Get-Process -Id $PID).Path
865:     $bgLine = ''
866:     if ($script:OnWindows) {
867:         # cmd.exe would expand a %NAME% in these paths: refused rather than corrupted
868:         foreach ($pth in @($hostExe, $script:SelfPath, $collabRoot, $paths.Log)) {
869:             if ($pth.Contains('%')) { Stop-WithError "-Detach starts its background through cmd.exe, which would expand the '%' in '$pth'; run without -Detach; nothing was started." }
870:         }
871:         $collabArg = $collabRoot
872:         # a trailing backslash would escape the closing quote
873:         if ($collabArg.EndsWith('\')) { $collabArg += '.' }
874:         $inner = '"' + $hostExe + '" -NoProfile -ExecutionPolicy Bypass -File "' + $script:SelfPath + '" -Task ' + $Task + ' -CollabDir "' + $collabArg + '" -DetachId ' + $newId + ' <NUL 1>"' + $paths.Log + '" 2>&1'
875:         $bgLine = '/d /v:off /s /c "' + $inner + '"'
876:     } else {
877:         $q = { param([string]$s) "'" + $s.Replace("'", "'\''") + "'" }
878:         $bgLine = 'exec nohup ' + (& $q $hostExe) + ' -NoProfile -File ' + (& $q $script:SelfPath) + ' -Task ' + (& $q $Task) + ' -CollabDir ' + (& $q $collabRoot) + ' -DetachId ' + $newId + ' </dev/null >' + (& $q $paths.Log) + ' 2>&1'
879:     }
880:     # The `starting` record, written ONCE, before the background exists (D5).
881:     $rec = ConvertTo-DetachedRecord @{
882:         status_version = $script:DetachedStatusVersion; id = $newId; id8 = $paths.Id8; task = $Task; kind = $Kind; state = 'starting'
883:         started = (Get-IsoTimestamp); host = [Environment]::MachineName; budget_sec = $Budget; purpose = $Purpose; reply_name = $ReplyName
884:         brief = $BriefFull; members = [object[]]@($Members | Where-Object { $_ }); log = $paths.Log; args = (ConvertTo-DetachArgs -Arguments $bgArgs)
885:     }
886:     try { Write-DetachedStatus -Path $paths.Status -Record $rec } catch {
887:         $why = ConvertTo-OneLine $_.Exception.Message
888:         if ($promptFile) { $null = Remove-PendingFile -Path $promptFile }
889:         Stop-WithError "could not write the status file '$($paths.Status)' ($why); nothing was started."
890:     }
891:     try {
892:         if ($script:OnWindows) {
893:             $cmdExe = [string]$env:ComSpec
894:             if (-not $cmdExe) { $cmdExe = 'cmd.exe' }
895:             # ShellExecute (no -NoNewWindow, no redirection here): the background inherits none of
896:             # this process's handles, so the caller's pipes close when this process exits
897:             $null = Start-Process -FilePath $cmdExe -ArgumentList $bgLine -WorkingDirectory $callerCwd -WindowStyle Hidden -PassThru
898:         } else {
899:             $psi = New-Object System.Diagnostics.ProcessStartInfo
900:             $psi.FileName = '/bin/sh'
901:             [void]$psi.ArgumentList.Add('-c')
902:             [void]$psi.ArgumentList.Add($bgLine)
903:             $psi.UseShellExecute = $false
904:             $psi.WorkingDirectory = $callerCwd
905:             $null = [System.Diagnostics.Process]::Start($psi)
906:         }
907:     } catch {
908:         $why = ConvertTo-OneLine $_.Exception.Message
909:         $rmError = Remove-PendingFile -Path $paths.Status
910:         if ($promptFile) { $null = Remove-PendingFile -Path $promptFile }
911:         Stop-WithError "could not start the background process ($why); nothing was started$(if ($rmError) { " (the status file '$($paths.Status)' could not be removed: $rmError)" })."
912:     }
913:     foreach ($w in @($Warnings | Where-Object { $_ })) { Write-Host "WARNING: $w" -ForegroundColor Yellow }
914:     $collabOpt = $(if ($script:ScriptBound.ContainsKey('CollabDir')) { " -CollabDir `"$collabRoot`"" } else { '' })
915:     Write-Host "Detached $($paths.Id8): $Plan - it runs in the background (detach id $newId; budget $Budget s)."
916:     Write-Host "status file: $($paths.Status) (console output: $($paths.Log))"
917:     Write-Host "come back  : codex-consult.ps1 -Task $Task$collabOpt -Status -Id $($paths.Id8) (exit 0 done and usable, 1 a failure, 2 still running); -Wait -Id $($paths.Id8) waits until it is done (default: its budget, $Budget s)"
918:     exit 0
919: }
