1370:     if (-not $refusal -and $engineName -ne 'codex') { $refusal = Get-CmdArgvHazard -Launcher $Launcher -Argv $Argv }
1371:     if ($refusal) { $r.Refusal = [string]$refusal; return $r }
1372:     try {
1373:         $r.Proc = Start-Process -FilePath $Launcher -ArgumentList ((($Argv | ForEach-Object { ConvertTo-ProcArg $_ }) -join ' ')) `
1374:             -WorkingDirectory $repoRoot -NoNewWindow -PassThru `
1375:             -RedirectStandardOutput $StdoutPath `
1376:             -RedirectStandardError $StderrPath `
1377:             -RedirectStandardInput $StdinPath
