1384: # One more turn (an engine's denial retry and format repair; wave 24: the timeout continuation
1385: # of every engine, codex included) under the SAME task lock and recovery record as the run: the
1386: # record goes launching -> running (child pid, start time, `events` = this turn's event stream)
1387: # before the process is waited on; a timeout kills the process tree, and survivors are recorded
1388: # (state survivors) and keep the record.
1389: # -PromptPath / -PromptText (wave 23, D1): the turn's own prompt file, written first (muse
1390: # names it in its argv; its stdin is then empty). Right before the start (Start-EngineProcess)
1391: # the engine's launch invariant (D4; read afresh - wave 24, F15-1) and, for an engine other than
1392: # codex, the .cmd %-hazard (F02-14) are checked again: a refusal starts nothing (the record gets
1393: # its previous state back - (wave 24c, F15-6) so does a Start-Process error: every path that
1394: # starts nothing).
1395: # Reads the run's $pendingRecord, $pendingPath, $engineLauncher, $engineName and $repoRoot.
1396: # { Exit (-1 unless it exited); Problem ('' or why the turn did not complete); Wall;
1397: # KeepPending; Stderr (UTF-8 text); Started (a process was started: one more engine turn -
1398: # for muse one more subscription prompt) }.
1399: function Invoke-EngineTurn {
1400:     param([string[]]$Argv, [string]$StdinText, [string]$EventsPath, [string]$StdinPath, [string]$StderrPath, [int]$Timeout, [string]$Note, [string]$PromptPath = '', [string]$PromptText = '')
1401:     $t = [pscustomobject]@{ Exit = -1; Problem = ''; Wall = 0; KeepPending = $false; Stderr = ''; Started = $false }
1402:     if ($PromptPath) { Write-Utf8NoBom -Path $PromptPath -Text $PromptText }
1403:     Write-Utf8NoBom -Path $StdinPath -Text $StdinText
1404:     $watch = [System.Diagnostics.Stopwatch]::StartNew()
1405:     $prevState = [string]$pendingRecord.state
1406:     $prevNote = [string]$pendingRecord.note
1407:     $pendingRecord.state = 'launching'
1408:     $pendingRecord.note = "$Note being started; its pid is not recorded yet"
1409:     try { Write-PendingFile -Path $pendingPath -Record $pendingRecord } catch {
1410:         $t.Problem = "could not write the recovery record ($(ConvertTo-OneLine $_.Exception.Message)); the turn was not started"
1411:         # (the record on disk still has its previous state: so does the one in memory)
1412:         $pendingRecord.state = $prevState
1413:         $pendingRecord.note = $prevNote
1414:         return $t
1415:     }
1416:     $launch = Start-EngineProcess -Launcher $engineLauncher -Argv $Argv -StdoutPath $EventsPath -StderrPath $StderrPath -StdinPath $StdinPath
1417:     $proc = $launch.Proc
1418:     if (-not $proc) {
1419:         # (wave 24c, F15-6) NOTHING was started - a launch refusal or a Start-Process error (a
1420:         # launcher gone meanwhile): on every such path the record gets its previous state back. A
1421:         # record left `launching` would tell the next run (after a bridge that died before its
1422:         # commit) that a process may be starting - it would scan for one that never existed.
1423:         $pendingRecord.state = $prevState
1424:         $pendingRecord.note = $prevNote
1425:         try { Write-PendingFile -Path $pendingPath -Record $pendingRecord } catch { }
1426:         if ($launch.Refusal) {
1427:             $t.Problem = "refused before launch: $($launch.Refusal)"
1428:             return $t
1429:         }
1430:         $t.Problem = "could not start $engineName$(if ($launch.Error) { " - $($launch.Error)" })"
1431:     }
1432:     if ($proc) {
1433:         if ($script:LegacyPS) { try { $null = $proc.Handle } catch { } }
1434:         $t.Started = $true
1435:         $registered = $true
1436:         try {
1437:             $pendingRecord.state = 'running'
1438:             $pendingRecord.child_pid = $proc.Id
1439:             $pendingRecord.child_start_time = [string](Get-ProcessStartIso -ProcessId $proc.Id)
1440:             $pendingRecord.note = $Note
1441:             $evRel = Get-RepoRelativePath -Root $repoRoot -Path $EventsPath
1442:             $pendingRecord.events = $(if ($evRel) { $evRel } else { $EventsPath })
1443:             Write-PendingFile -Path $pendingPath -Record $pendingRecord
1444:         } catch {
1445:             $registered = $false
1446:             $t.Problem = "could not register the $Note process ($(ConvertTo-OneLine $_.Exception.Message)); it was stopped"
1447:             # the record on disk still says launching: so does the one in memory
1448:             $pendingRecord.state = 'launching'; $pendingRecord.child_pid = $null; $pendingRecord.child_start_time = ''
1449:             $null = Stop-ProcessTree -Process $proc
1450:         }
1451:         if ($registered) {
1452:             if (-not $proc.WaitForExit($Timeout * 1000)) {
1453:                 $surv = Stop-ProcessTree -Process $proc   # [int[]]; never wrap in @()
1454:                 $t.Problem = "timeout after $Timeout s (process tree killed)"
1455:                 if ($surv.Count -gt 0) {
1456:                     $t.Problem = "timeout after $Timeout s (process tree killed; $($surv.Count) processes survived: pid $($surv -join ', '))"
1457:                     $t.KeepPending = $true
1458:                     try {
1459:                         $pendingRecord.state = 'survivors'
1460:                         $pendingRecord.survivors = [object[]]@(New-SurvivorEntries -Pids $surv)
1461:                         Write-PendingFile -Path $pendingPath -Record $pendingRecord
1462:                     } catch { }
1463:                 }
1464:             } else {
1465:                 $t.Exit = $proc.ExitCode
1466:             }
1467:         }
1468:     }
1469:     $watch.Stop()
1470:     $t.Wall = [math]::Round($watch.Elapsed.TotalSeconds, 1)
1471:     $t.Stderr = Read-SharedText -Path $StderrPath
1472:     return $t
