5568: # The roster walk: the first entry whose preflight verdict (Get-PreflightVerdict
5569: # -RosterWalk) is available. $Model (an explicit -Model without -Provider) restricts the walk
5570: # to the entries that resolve to that model. -SkipPreflight takes the first entry unchecked -
5571: # except for an engine's launch invariant (wave 23, D4: muse's billing guard), which skips an
5572: # entry ("refused: ...") with and without -SkipPreflight.
5573: # { Entry; Identity; Verdict; Skipped (object[] of { provider; model; reason }, in roster
5574: # order - never a List: @() over a List property fails on Windows PowerShell 5.1);
5575: # Considered (entries walked); Error ('' or the refusal: none available / no entry for
5576: # $Model / the first entry's identity error under -SkipPreflight) }.
5577: function Select-RosterReviewer {
5578:     param($Roster, $Config, [object[]]$Consults, [string]$Launcher, [hashtable]$LoginCache = $null, [datetime]$UtcNow = [datetime]::UtcNow, [string]$OpenAiBaseUrl = '', [string]$Model = '', [switch]$SkipPreflight, [string]$Engine = '', [hashtable]$EngineLaunchers = $null, [switch]$NoNetwork, [hashtable]$Cache = $null)
5579:     $skipped = New-Object System.Collections.Generic.List[object]
5580:     $r = [pscustomobject]@{ Entry = $null; Identity = $null; Verdict = $null; Skipped = [object[]]@(); Considered = 0; Error = '' }
5581:     $listing = New-Object System.Collections.Generic.List[string]
5582:     foreach ($e in @($Roster.Entries)) {
5583:         $entryEngine = if ($e.PSObject.Properties['Engine'] -and $e.Engine) { [string]$e.Engine } else { 'codex' }
5584:         if ($Engine -and $entryEngine -ne $Engine) { continue }
5585:         $entryLauncher = Get-EngineLauncher -Engine $entryEngine -Launchers $EngineLaunchers -CodexLauncher $Launcher
5586:         $id = Get-CachedReviewerIdentity -Cache $Cache -Config $Config -Provider $e.Provider -Model $e.Model -OpenAiBaseUrl $OpenAiBaseUrl -Engine $entryEngine -Launcher $entryLauncher
5587:         if ($Model -and $id.Model -cne $Model) { continue }
5588:         $r.Considered++
5589:         $block = Get-EngineLaunchBlock -Engine $entryEngine
5590:         if ($block) {
5591:             $skipped.Add([pscustomobject]@{ provider = $e.Provider; model = $id.Model; engine = $entryEngine; reason = "refused: $block" })
5592:             $listing.Add("#$($e.Position) $(Format-ReviewerLineage -Provider $id.Provider -Model $id.Model -Engine $entryEngine) (refused: $block)")
5593:             continue
5594:         }
5595:         if ($SkipPreflight) {
5596:             if ($id.Error) { $r.Error = $id.Error; return $r }
5597:             $r.Entry = $e; $r.Identity = $id
5598:             $r.Skipped = [object[]]$skipped.ToArray()
5599:             return $r
5600:         }
5601:         $health = $null
5602:         if ($id.Resolved) { $health = Get-CachedEndpointHealth -Cache $Cache -Consults $Consults -Fingerprint $id.Fingerprint -UtcNow $UtcNow }
5603:         $verdict = Get-PreflightVerdict -Identity $id -Config $Config -Launcher $entryLauncher -Health $health -LoginCache $LoginCache -Anonymous:($e.Auth -eq 'none') -RosterWalk -NoNetwork:$NoNetwork
5604:         if ($verdict.State -eq 'available') {
5605:             $r.Entry = $e; $r.Identity = $id; $r.Verdict = $verdict
5606:             $r.Skipped = [object[]]$skipped.ToArray()
5607:             return $r
5608:         }
5609:         $skipped.Add([pscustomobject]@{ provider = $e.Provider; model = $id.Model; engine = $entryEngine; reason = $verdict.Reason })
5610:         $listing.Add("#$($e.Position) $(Format-ReviewerLineage -Provider $id.Provider -Model $id.Model -Engine $entryEngine) ($($verdict.Reason))")
5611:     }
5612:     if ($r.Considered -eq 0) {
5613:         $all = (@($Roster.Entries) | ForEach-Object { "#$($_.Position) $(if ($_.Model) { Format-ReviewerLineage -Provider $_.Provider -Model $_.Model -Engine $_.Engine } else { "$($_.Provider) (config model)" })" }) -join ', '
5614:         if ($Engine -and -not $Model) {
5615:             $r.Error = "-Engine $($Engine): no entry of the reviewer roster '$($Roster.Path)' uses that engine ($all); pass -Provider <label> -Model <model> to choose a reviewer outside the roster"
5616:         } else {
5617:             $r.Error = "-Model $($Model): no entry of the reviewer roster '$($Roster.Path)' resolves to that model ($all); pass -Provider <name> -Model $Model to choose a reviewer outside the roster"
5618:         }
5619:         return $r
5620:     }
5621:     $r.Skipped = [object[]]$skipped.ToArray()
5622:     $r.Error = "no reviewer of the roster '$($Roster.Path)' is available; nothing was started: $($listing.ToArray() -join '; ') (run codex-providers.ps1 for the full picture)"
5623:     return $r
5624: }
