5626: # The purposes on which a "weighty" roster entry joins a panel.
5627: $script:WeightyPurposes = @('framing', 'decision', 'core-contract', 'acceptance', 'stuck')
5628: 
5629: # The members of a review panel (-Panel): the roster walked like Select-RosterReviewer
5630: # without stopping at the first available entry. Every entry whose preflight verdict is
5631: # available (with -SkipPreflight: every entry) runs, unless it is "weighty" and $Purpose is
5632: # light (not in $script:WeightyPurposes) and -All (-PanelAll) is not given, or its engine's
5633: # launch invariant refuses it (wave 23, D4 - with -SkipPreflight too). $Model: as for
5634: # the walk. -NoNetwork (wave 24, D15): passed to every preflight (an engine's sign-in that
5635: # needs the network is then "not checked") - the availability view of the hook and the listing
5636: # (Get-RosterAvailability) judges EVERY entry this way. { Members (object[], roster order, of {
5637: # Entry; Identity; State 'run'|'skipped'; Reason ('' when it runs); Verdict (the preflight
5638: # verdict, $null under -SkipPreflight or a launch refusal); Health (the endpoint health, $null
5639: # when unresolved); Block ('' or the launch refusal); SkipKind (wave 26: '' | refused |
5640: # unavailable | weighty - why it is skipped) }); Error ('' or the refusal: nobody runs / no entry
5641: # for $Model) }. (wave 26) Select-PanelRouting then seats the panel among the members that run
5642: # (State 'not-picked' for the rest).
5643: function Select-PanelMembers {
5644:     param($Roster, $Config, [object[]]$Consults, [string]$Launcher, [hashtable]$LoginCache = $null, [datetime]$UtcNow = [datetime]::UtcNow, [string]$OpenAiBaseUrl = '', [string]$Model = '', [string]$Purpose = '', [switch]$All, [switch]$SkipPreflight, [string]$Engine = '', [hashtable]$EngineLaunchers = $null, [switch]$NoNetwork, [hashtable]$Cache = $null)
5645:     $members = New-Object System.Collections.Generic.List[object]
5646:     $r = [pscustomobject]@{ Members = [object[]]@(); Error = '' }
5647:     $listing = New-Object System.Collections.Generic.List[string]
5648:     $purposeLabel = if ($Purpose) { $Purpose } else { 'none' }
5649:     foreach ($e in @($Roster.Entries)) {
5650:         $entryEngine = if ($e.PSObject.Properties['Engine'] -and $e.Engine) { [string]$e.Engine } else { 'codex' }
5651:         if ($Engine -and $entryEngine -ne $Engine) { continue }
5652:         $entryLauncher = Get-EngineLauncher -Engine $entryEngine -Launchers $EngineLaunchers -CodexLauncher $Launcher
5653:         $id = Get-CachedReviewerIdentity -Cache $Cache -Config $Config -Provider $e.Provider -Model $e.Model -OpenAiBaseUrl $OpenAiBaseUrl -Engine $entryEngine -Launcher $entryLauncher
5654:         if ($Model -and $id.Model -cne $Model) { continue }
5655:         $state = 'run'
5656:         $reason = ''
5657:         $skipKind = ''
5658:         $verdict = $null
5659:         $health = $null
5660:         if ($id.Resolved) { $health = Get-CachedEndpointHealth -Cache $Cache -Consults $Consults -Fingerprint $id.Fingerprint -UtcNow $UtcNow }
5661:         $block = Get-EngineLaunchBlock -Engine $entryEngine
5662:         if ($block) { $state = 'skipped'; $reason = "refused: $block"; $skipKind = 'refused' }
5663:         elseif (-not $SkipPreflight) {
5664:             $verdict = Get-PreflightVerdict -Identity $id -Config $Config -Launcher $entryLauncher -Health $health -LoginCache $LoginCache -Anonymous:($e.Auth -eq 'none') -RosterWalk -NoNetwork:$NoNetwork
5665:             if ($verdict.State -ne 'available') { $state = 'skipped'; $reason = $verdict.Reason; $skipKind = 'unavailable' }
5666:         }
5667:         if ($state -eq 'run' -and $e.Panel -eq 'weighty' -and -not $All -and $script:WeightyPurposes -notcontains $Purpose) {
5668:             $state = 'skipped'
5669:             $reason = "weighty reviewer; purpose $purposeLabel is light (use -PanelAll)"
5670:             $skipKind = 'weighty'
5671:         }
5672:         $members.Add([pscustomobject]@{ Entry = $e; Identity = $id; State = $state; Reason = $reason; Verdict = $verdict; Health = $health; Block = [string]$block; SkipKind = $skipKind })
5673:         $listing.Add("#$($e.Position) $(Format-ReviewerLineage -Provider $id.Provider -Model $id.Model -Engine $entryEngine) ($(if ($state -eq 'run') { 'runs' } else { $reason }))")
5674:     }
5675:     $r.Members = [object[]]$members.ToArray()
5676:     if ($members.Count -eq 0) {
5677:         $all = (@($Roster.Entries) | ForEach-Object { "#$($_.Position) $(if ($_.Model) { Format-ReviewerLineage -Provider $_.Provider -Model $_.Model -Engine $_.Engine } else { "$($_.Provider) (config model)" })" }) -join ', '
5678:         if ($Engine -and -not $Model) {
5679:             $r.Error = "-Engine $($Engine): no entry of the reviewer roster '$($Roster.Path)' uses that engine ($all)"
5680:         } else {
5681:             $r.Error = "-Model $($Model): no entry of the reviewer roster '$($Roster.Path)' resolves to that model ($all); pass -Provider <name> -Model $Model to choose a reviewer outside the roster"
5682:         }
5683:     } elseif (@($members | Where-Object { $_.State -eq 'run' }).Count -eq 0) {
5684:         $r.Error = "no reviewer of the roster '$($Roster.Path)' is available; nothing was started: $($listing.ToArray() -join '; ') (run codex-providers.ps1 for the full picture)"
5685:     }
5686:     return $r
5687: }
