5692: function Format-RequiredOutage {
5693:     param($Member, [datetime]$UtcNow = [datetime]::UtcNow)
5694:     $shown = Format-ReviewerLineage -Provider ([string]$Member.Identity.Provider) -Model ([string]$Member.Identity.Model) -Engine ([string]$Member.Entry.Engine)
5695:     $text = "#$($Member.Entry.Position) $shown ($($Member.Reason)"
