5699:         $now = New-Object DateTimeOffset ([datetime]::SpecifyKind($UtcNow, [DateTimeKind]::Utc))
5700:         $text += "; back $(Format-LocalWhen -When $until -NowUtc $UtcNow), $(Format-RelativeHint ($until - $now))"
