5705: # ----------------------------------------------------------------------------- telemetry routing (wave 26, R15)
5706: #
5707: # The judge's marks (codex-findings.ps1 -Rate) of EVERY task of the repository, scored per
5708: # reviewer (D2, D3) - one function for the bridge's panel routing and codex-scoreboard.ps1:
5709: #   evidence   the ratings of the last 90 days by the CONSULTATION's time (rating.consult_when,
5710: #              else - a rating recorded before wave 26 - the ledger entry with its consult_id,
5711: #              else the rating's own time); the latest rating of a consultation wins (keyed by
5712: #              consult_id; a rating without one by task and n); every field is read from the
5713: #              rating record itself (denormalised at -Rate time) - no join by n across tasks
5714: #   rate       w = (yes + 0.5 partly + 2p) / (n + 4p), p = 0.5 - a rate with a prior that pulls
5715: #              few ratings to 0.5; the score = 0.25 + 1.75 w, in [0.25, 2]; neutral = 1.125
5716: #   hierarchy  (lineage, purpose, topics) when the pooled topic evidence reaches 3 ratings, else
5717: #              (lineage, purpose) with >= 3, else the lineage's all-purpose rate with >= 3, else
5718: #              neutral. A rating credits each of its t topics 1/t; a request with topics pools the
5719: #              credited counts over its topics (never a mean of means)
5720: $script:RoutingWindowDays = 90
5721: $script:RoutingMinRatings = 3
5722: $script:RoutingPrior = 0.5
5723: $script:RoutingExplore = 0.2
5724: $script:RoutingNeutral = 0.25 + 1.75 * 0.5
5725: 
5726: # Every rating of every task under $CollabRoot, normalised: { Key; Task; N; ConsultId; Provider;
5727: # Model; Engine; Lineage; Purpose; Topics (string[]); ConsultWhen (DateTimeOffset or $null);
5728: # RatedWhen; Useful (yes | partly | no) }. A findings.json that does not parse is left out (read
5729: # tolerantly, like Read-AllTaskConsults); a rating without a provider (unknown provenance) or with
5730: # another mark is left out. $Consults (Read-AllTaskConsults; read here when $null) resolves a
5731: # pre-wave-26 rating's missing fields by its consult_id - never by n. Duplicates: the latest
5732: # rating (RatedWhen) of a consultation wins. $Stores (hashtable: task directory name -> its parsed
5733: # findings.json, $null when none): stores the caller already read (the scoreboard reads each
5734: # findings.json once per run - D2); without it every task's findings.json is read here.
5735: function Read-AllTaskRatings {
=== 5958-6145 ===
5958: # The panel's routing (wave 26; D1, D4-D7): who of Select-PanelMembers' members takes a seat.
5959: #   eligible   State 'run' (available, the weighty gate passed, -Engine/-Model matched) - one set
5960: #              for the ranking, the draw and exploration (D1, D11); a REQUIRED entry that only the
5961: #              weighty gate held back is eligible too (the caller refuses a required entry that is
5962: #              out, exit 5)
5963: #   size       $Size (0 = every eligible member: -PanelAll, stuck), at least the required count,
5964: #              at most the eligible count; the size bounds the members STARTED - no backfill
5965: #   mode       $Order 'roster': the required, then the rest in roster order, no draw (D5); 'routed':
5966: #              the seeded draw of Invoke-PanelDraw over the scores (Get-RoutingScore) - unless NO
5967: #              eligible reviewer has >= 3 ratings in the window: then roster order, fallback
5968: #              'no ratings' (no shuffle without evidence)
5969: # Members that are eligible but get no seat: State 'not-picked', Reason 'panel size <k>'. Every
5970: # member gains Lineage, Lab, LabSource, Score (Get-RoutingScore), Required, Rule, Slot.
5971: # { Members (roster order); Picked (seat order); K; Routing (the ledger's panel.routing: mode,
5972: # order, fallback, seed, nonce, nonce_source, size, size_source, eligible[{position, lineage, lab,
5973: # lab_source, score, basis, ratings, required}], picked[{slot, position, lineage, lab, rule}],
5974: # explored[lineage], required[lineage]); Warnings (string[]: a singleton lab in a routed panel,
5975: # the floor) }.
5976: function Select-PanelRouting {
5977:     param([object[]]$Members, [int]$Size = 0, [string]$SizeSource = 'purpose', [string]$Order = 'routed', [object[]]$Ratings = @(), [string]$Purpose = '', [string[]]$Topics = @(), [datetime]$UtcNow = [datetime]::UtcNow, [string]$Task = '', [string]$BriefSha = '', [string]$Nonce = '', [string]$NonceSource = 'date', [int[]]$Required = @())
5978:     $neutral = $script:RoutingNeutral
5979:     $req = @($Required | ForEach-Object { [int]$_ })
5980:     foreach ($m in @($Members | Where-Object { $_ })) {
5981:         $isReq = ($req -contains [int]$m.Entry.Position)
5982:         if ($isReq -and $m.State -eq 'skipped' -and [string](Get-PropertyValue $m 'SkipKind' '') -eq 'weighty') { $m.State = 'run'; $m.Reason = '' }
5983:         $engine = [string]$m.Identity.Engine
5984:         if (-not $engine) { $engine = [string]$m.Entry.Engine }
5985:         if (-not $engine) { $engine = 'codex' }
5986:         $lineage = Format-ReviewerLineage -Provider ([string]$m.Identity.Provider) -Model ([string]$m.Identity.Model) -Engine $engine
5987:         $lab = Get-EntryLab -Entry $m.Entry -Model ([string]$m.Identity.Model) -Lineage $lineage
5988:         $score = Get-RoutingScore -Ratings $Ratings -Provider ([string]$m.Identity.Provider) -Model ([string]$m.Identity.Model) -Engine $engine -Purpose $Purpose -Topics $Topics -UtcNow $UtcNow
5989:         $m | Add-Member -NotePropertyName 'Lineage' -NotePropertyValue $lineage -Force
5990:         $m | Add-Member -NotePropertyName 'Lab' -NotePropertyValue ([string]$lab.Lab) -Force
5991:         $m | Add-Member -NotePropertyName 'LabSource' -NotePropertyValue ([string]$lab.Source) -Force
5992:         $m | Add-Member -NotePropertyName 'Score' -NotePropertyValue $score -Force
5993:         $m | Add-Member -NotePropertyName 'Required' -NotePropertyValue ([bool]$isReq) -Force
5994:         $m | Add-Member -NotePropertyName 'Rule' -NotePropertyValue '' -Force
5995:         $m | Add-Member -NotePropertyName 'Slot' -NotePropertyValue 0 -Force
5996:     }
5997:     $eligible = @($Members | Where-Object { $_ -and $_.State -eq 'run' })
5998:     $k = $Size
5999:     if ($k -le 0) { $k = $eligible.Count }
6000:     $pinned = @($eligible | Where-Object { $_.Required })
6001:     if ($k -lt $pinned.Count) { $k = $pinned.Count }
6002:     if ($k -gt $eligible.Count) { $k = $eligible.Count }
6003:     $mode = $Order
6004:     $fallback = ''
6005:     if ($mode -eq 'routed' -and @($eligible | Where-Object { $_.Score.All -ge $script:RoutingMinRatings }).Count -eq 0) { $mode = 'roster'; $fallback = 'no ratings' }
6006:     $seed = Get-PanelSeed -Task $Task -Purpose $Purpose -BriefSha $BriefSha -Lineages ([string[]]@($eligible | ForEach-Object { $_.Lineage })) -Nonce $Nonce
6007:     $seats = New-Object System.Collections.Generic.List[object]
6008:     if ($mode -eq 'routed') {
6009:         $cands = @($eligible | ForEach-Object { [pscustomobject]@{ Position = [int]$_.Entry.Position; Lab = [string]$_.Lab; Weight = [double]$_.Score.Score; Pinned = [bool]$_.Required; Member = $_ } })
6010:         foreach ($s in (Invoke-PanelDraw -Candidates $cands -K $k -Seed $seed.Bytes)) { $seats.Add([pscustomobject]@{ Slot = $s.Slot; Member = $s.Candidate.Member; Rule = $s.Rule }) }
6011:     } else {
6012:         $chosen = New-Object System.Collections.Generic.List[object]
6013:         foreach ($m in $pinned) { $chosen.Add($m) }
6014:         foreach ($m in @($eligible | Where-Object { -not $_.Required })) { if ($chosen.Count -ge $k) { break }; $chosen.Add($m) }
6015:         # the required take the first seats (D7), then the roster order
6016:         $slot = 0
6017:         foreach ($m in $chosen) { $slot++; $seats.Add([pscustomobject]@{ Slot = $slot; Member = $m; Rule = $(if ($m.Required) { 'required' } else { 'roster' }) }) }
6018:     }
6019:     foreach ($s in $seats) { $s.Member.Rule = $s.Rule; $s.Member.Slot = $s.Slot }
6020:     foreach ($m in $eligible) {
6021:         if ($m.Slot -le 0) { $m.State = 'not-picked'; $m.Reason = "panel size $k" }
6022:     }
6023:     $warnings = New-Object System.Collections.Generic.List[string]
6024:     if ($mode -eq 'routed') {
6025:         foreach ($m in @($eligible | Where-Object { $_.LabSource -eq 'singleton' })) {
6026:             $warnings.Add("routing: no lab known for #$($m.Entry.Position) $($m.Lineage) (its model id has no known vendor prefix) - it counts as a lab of its own; give its roster entry a ""lab""")
6027:         }
6028:     }
6029:     if ($SizeSource -ne '-PanelSize' -and $script:PanelFloorPurposes -contains $Purpose -and $seats.Count -lt 2) {
6030:         $warnings.Add("panel floor: a $Purpose panel runs $($seats.Count) member$(if ($seats.Count -ne 1) { 's' }) - $Purpose questions should hear at least 2 reviewers (pass -PanelSize to choose the size explicitly)")
6031:     }
6032:     $round = { param([double]$x, [int]$d) [Math]::Round($x, $d) }
6033:     $routing = [pscustomobject]@{
6034:         mode         = $mode
6035:         order        = $Order
6036:         fallback     = $fallback
6037:         seed         = $seed.Hex
6038:         nonce        = $Nonce
6039:         nonce_source = $NonceSource
6040:         size         = $k
6041:         size_source  = $SizeSource
6042:         eligible     = [object[]]@($eligible | ForEach-Object { [pscustomobject]@{ position = [int]$_.Entry.Position; lineage = $_.Lineage; lab = $_.Lab; lab_source = $_.LabSource; score = (& $round $_.Score.Score 4); basis = $_.Score.Basis; ratings = (& $round $_.Score.Ratings 2); required = [bool]$_.Required } })
6043:         picked       = [object[]]@($seats | ForEach-Object { [pscustomobject]@{ slot = $_.Slot; position = [int]$_.Member.Entry.Position; lineage = $_.Member.Lineage; lab = $_.Member.Lab; rule = $_.Rule } })
6044:         explored     = [object[]]@($seats | Where-Object { $_.Rule -like '*-explore' } | ForEach-Object { $_.Member.Lineage })
6045:         required     = [object[]]@($pinned | ForEach-Object { $_.Lineage })
6046:     }
6047:     return [pscustomobject]@{ Members = [object[]]@($Members); Picked = [object[]]@($seats | ForEach-Object { $_.Member }); K = $k; Routing = $routing; Warnings = [string[]]$warnings.ToArray() }
6048: }
