6069: # ----------------------------------------------------------------------------- roles (wave 26, R16)
6070: #
6071: # A role narrows what a reviewer looks at (D8): a Markdown block inserted into the prompt after the
6072: # ask and before the brief - never inside the output contract; the verdict rules, the read-only
6073: # sandbox and the reply format stay as they are. A role name is a slug (checked before any path is
6074: # built); `<CollabDir>/roles/<name>.md` of the repository wins over the plugin's
6075: # `templates/role-<name>.md` (edge-cases, security, tests, docs ship). { Name; Path; Source
6076: # ('repository' | 'plugin'); Text; Error }.
6077: function Resolve-RoleFile {
6078:     param([string]$Name, [string]$CollabRoot = '', [string]$PluginRoot = '')
6079:     $r = [pscustomobject]@{ Name = $Name; Path = ''; Source = ''; Text = ''; Error = '' }
6080:     if ($Name -cnotmatch $script:SlugPattern) { $r.Error = "role '$Name' is not a slug (lowercase letters, digits, dot, dash, underscore)"; return $r }
6081:     $candidates = New-Object System.Collections.Generic.List[object]
6082:     if ($CollabRoot) { $candidates.Add(@((Join-Path (Join-Path $CollabRoot 'roles') "$Name.md"), 'repository')) }
6083:     if ($PluginRoot) { $candidates.Add(@((Join-Path (Join-Path $PluginRoot 'templates') "role-$Name.md"), 'plugin')) }
6084:     foreach ($c in $candidates) {
6085:         if (Test-Path -LiteralPath $c[0] -PathType Leaf) {
6086:             $text = (Read-SharedText -Path $c[0]).Trim()
6087:             if (-not $text) { $r.Error = "the role file '$($c[0])' is empty"; return $r }
6088:             $r.Path = $c[0]; $r.Source = $c[1]; $r.Text = $text
6089:             return $r
6090:         }
6091:     }
6092:     $known = New-Object System.Collections.Generic.List[string]
6093:     foreach ($c in $candidates) {
6094:         $dir = Split-Path -Parent $c[0]
6095:         if (-not (Test-Path -LiteralPath $dir -PathType Container)) { continue }
6096:         foreach ($f in @(Get-ChildItem -LiteralPath $dir -File -Filter '*.md' -ErrorAction SilentlyContinue)) {
6097:             $n = $f.BaseName
6098:             if ($c[1] -eq 'plugin') { if ($n -notlike 'role-*') { continue }; $n = $n.Substring(5) }
6099:             if ($n -cmatch $script:SlugPattern -and -not $known.Contains($n)) { $known.Add($n) }
6100:         }
6101:     }
6102:     $r.Error = "unknown role '$Name' (no $(if ($CollabRoot) { "$(Join-Path (Join-Path $CollabRoot 'roles') "$Name.md") nor " })templates/role-$Name.md; known: $(if ($known.Count -gt 0) { ($known.ToArray() | Sort-Object) -join ', ' } else { 'none' }))"
6103:     return $r
6104: }
